import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.concurrent.CompletableFuture;
import java.util.function.Function;

public class IoSideEffectManager {

    // Pure function transforming data without side-effects
    private static final Function<ByteBuffer, ByteBuffer> transformBuffer = buffer -> {
        buffer.flip();
        while (buffer.hasRemaining()) {
            buffer.put(buffer.position(), (byte) (buffer.get() ^ 0xAA));
        }
        buffer.rewind();
        return buffer;
    };

    // Side-effecting I/O boundary operation
    public CompletableFuture<Void> writeToFileAsync(Path path, byte[] data) {
        return CompletableFuture.runAsync(() -> {
            ByteBuffer buffer = ByteBuffer.wrap(data);
            ByteBuffer processedBuffer = transformBuffer.apply(buffer);

            try (FileChannel channel = FileChannel.open(path, StandardOpenOption.WRITE, StandardOpenOption.CREATE)) {
                while (processedBuffer.hasRemaining()) {
                    channel.write(processedBuffer);
                }
            } catch (IOException e) {
                throw new RuntimeException("Failed to execute NIO write side-effect", e);
            }
        });
    }
}
